import{_ as e}from"./chunks/ptz-camera.3CcqwwCG.js";import{_ as r,a as t,b as o,c as i,d as n,e as s,f as c}from"./chunks/rbq10-charger.CbRxhaKy.js";import{_ as d}from"./chunks/battery.C4otYI_6.js";import{_ as l}from"./chunks/docking-station.BN1LEeb4.js";import{_ as h,o as p,c as m,a5 as u}from"./chunks/framework.BjM_ivYE.js";const R=JSON.parse('{"title":"Accessories","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"manual/product-descriptions/accessories.md","filePath":"manual/product-descriptions/accessories.md","lastUpdated":1788840704000}'),b={name:"manual/product-descriptions/accessories.md"};function g(f,a,v,w,y,P){return p(),m("div",null,[...a[0]||(a[0]=[u('<h1 id="accessories" tabindex="-1">Accessories <a class="header-anchor" href="#accessories" aria-label="Permalink to &quot;Accessories&quot;">​</a></h1><p>RBQ supports a range of optional accessories that extend the robot for field missions and development work — sensing, onboard compute and connectivity, and power infrastructure.</p><h2 id="sensing" tabindex="-1">Sensing <a class="header-anchor" href="#sensing" aria-label="Permalink to &quot;Sensing {#sensing}&quot;">​</a></h2><div class="rbq-card-grid"><div class="rbq-card"><img src="'+e+'" alt=""><h3 id="ptz-camera">PTZ Camera<a class="header-anchor" href="#ptz-camera" aria-label="Permalink to PTZ Camera"></a></h3><p>A Pan-Tilt-Zoom camera that mounts on the RBQ body. Provides high-resolution video streaming for surveillance and reconnaissance missions with remote pan, tilt, and zoom control via the GUI and API.</p><a class="rbq-card-cta" href="/RBQ/manual/related-products/ptz-camera">Specifications →</a></div><div class="rbq-card"><img src="'+r+'" alt=""><h3 id="lidar-mid-360">LIDAR (mid-360)<a class="header-anchor" href="#lidar-mid-360" aria-label="Permalink to LIDAR (mid-360)"></a></h3><p>The Livox MID-360 is a compact 3D LiDAR with a hemispherical field of view (360° × 59°). Used for obstacle detection and autonomous navigation. Connects via Ethernet.</p><p>The <strong>MID-360S</strong> is Livox&#39;s next-generation model: 360° horizontal by −7°–52° vertical, 40 m range at 10% reflectivity, 200,000 points per second. On the RBQ it is <strong>mounted rotated 90° about the vertical axis</strong>, so its frames differ from the MID-360 — see the <a href="/RBQ/manual/hardware/coordinate-frames#mid-360s">transform matrices</a>.</p><a class="rbq-card-cta" href="/RBQ/manual/related-products/lidar#mid-360">Specifications →</a></div><div class="rbq-card"><img src="'+t+'" alt=""><h3 id="lidar-os1-32">LIDAR (OS1-32)<a class="header-anchor" href="#lidar-os1-32" aria-label="Permalink to LIDAR (OS1-32)"></a></h3><p>The Ouster OS1-32 is a 360° spinning LiDAR with 32 channels that delivers dense point clouds for wide-area 3D mapping.</p><a class="rbq-card-cta" href="/RBQ/manual/related-products/lidar#os1-32">Specifications →</a></div></div><h2 id="compute-connectivity" tabindex="-1">Compute &amp; Connectivity <a class="header-anchor" href="#compute-connectivity" aria-label="Permalink to &quot;Compute &amp;amp; Connectivity {#compute-connectivity}&quot;">​</a></h2><div class="rbq-card-grid"><div class="rbq-card"><img src="'+o+'" alt=""><h3 id="user-pc-module">User-PC Module<a class="header-anchor" href="#user-pc-module" aria-label="Permalink to User-PC Module"></a></h3><p>An embedded compute board that mounts inside the RBQ payload bay. Runs user applications, AI inference, and custom sensor processing directly on the robot. Offers multiple I/O interfaces for sensor integration.</p><p>Available options:</p><ul><li><strong>UP Xtreme i12</strong> — Intel Core i7 (12th gen)</li><li><strong>UP Xtreme i14</strong> — Intel Core i7 (14th gen)</li><li><strong>NVIDIA Jetson AGX Orin</strong> — for AI inference workloads</li></ul><p>For other PC configurations, please <a href="/RBQ/manual/support/">contact us</a>.</p><a class="rbq-card-cta" href="/RBQ/manual/interface/network#onboard-pcs-and-ip-addresses">Network &amp; IP →</a></div><div class="rbq-card"><img src="'+i+'" alt=""><h3 id="hub-module">Hub Module<a class="header-anchor" href="#hub-module" aria-label="Permalink to Hub Module"></a></h3><p>An interface hub that expands the number of usable <code>12V-LAN</code> ports, so more accessories can be connected at once. Simplifies wiring for multi-sensor payloads.</p><a class="rbq-card-cta" href="/RBQ/manual/interface/external-port">External ports →</a></div><div class="rbq-card"><img src="'+n+'" alt=""><h3 id="wifi-lte-gps-module">Wifi Module / LTE/GPS Module<a class="header-anchor" href="#wifi-lte-gps-module" aria-label="Permalink to Wifi Module / LTE/GPS Module"></a></h3><p>Wireless communication modules for remote operation. The WiFi module enables high-bandwidth local communication, while the LTE/GPS module provides wide-area cellular connectivity combined with positioning.</p><a class="rbq-card-cta" href="/RBQ/manual/interface/network">Network →</a></div></div><h2 id="power-charging" tabindex="-1">Power &amp; Charging <a class="header-anchor" href="#power-charging" aria-label="Permalink to &quot;Power &amp;amp; Charging {#power-charging}&quot;">​</a></h2><div class="rbq-card-grid"><div class="rbq-card"><img src="'+d+'" alt=""><h3 id="battery">Battery<a class="header-anchor" href="#battery" aria-label="Permalink to Battery"></a></h3><p>The detachable battery pack used by the RBQ. For long-duration operation, swap in a charged pack instead of waiting for a recharge.</p><a class="rbq-card-cta" href="/RBQ/manual/related-products/battery">Specifications →</a></div><div class="rbq-card"><img src="'+s+'" alt=""><h3 id="battery-charging-tray">Battery Charging Tray<a class="header-anchor" href="#battery-charging-tray" aria-label="Permalink to Battery Charging Tray"></a></h3><p>A two-bay tray for charging battery packs on their own, detached from the robot. To charge the packs without removing them, use the RBQ10 charger instead.</p><a class="rbq-card-cta" href="/RBQ/manual/related-products/battery">Battery specifications →</a></div><div class="rbq-card"><img src="'+c+'" alt=""><h3 id="rbq10-charger">RBQ10 Charger<a class="header-anchor" href="#rbq10-charger" aria-label="Permalink to RBQ10 Charger"></a></h3><p>The supplied charger, which connects directly to the charging port on top of the robot. Supports standard AC input and charges the battery packs in place.</p><a class="rbq-card-cta" href="/RBQ/manual/operation/charging">How to charge →</a></div><div class="rbq-card"><img src="'+l+'" alt=""><h3 id="docking-station">Docking Station<a class="header-anchor" href="#docking-station" aria-label="Permalink to Docking Station"></a></h3><p class="rbq-card-badges"><span class="rbq-badge">Dog House · Coming soon</span></p><p>An autonomous docking station that allows the RBQ to self-dock for automatic battery charging and storage. Eliminates manual battery swap for long-duration deployment scenarios.</p><a class="rbq-card-cta" href="/RBQ/manual/related-products/docking-station">Specifications →</a></div></div><h2 id="payload-cabling" tabindex="-1">Payload Cabling <a class="header-anchor" href="#payload-cabling" aria-label="Permalink to &quot;Payload Cabling {#payload-cabling}&quot;">​</a></h2><p>Cables for wiring your own payload into the robot&#39;s power and communication. The robot end mates directly with the MOCO waterproof connectors on the external port panel; the other end is wired to suit your equipment. Voltage and current limits and the pin assignment for each port are in <a href="/RBQ/manual/interface/external-port.html#user-port-pin-map">External ports</a>.</p><div class="rbq-card-grid"><div class="rbq-card"><h3 id="cable-12pin">12PIN MOCO — 12V + LAN<a class="header-anchor" href="#cable-12pin" aria-label="Permalink to 12PIN MOCO — 12V + LAN"></a></h3><p>Connects to the <code>12V/LAN</code> port on a version 2 panel and breaks out <strong>12 V power and Gigabit Ethernet</strong> in one run. For cameras and sensors that need both power and a network link.</p><a class="rbq-card-cta" href="/RBQ/manual/interface/external-port#lan-v2">Pin map →</a></div><div class="rbq-card"><h3 id="cable-4pin">4PIN MOCO — 48V + CAN<a class="header-anchor" href="#cable-4pin" aria-label="Permalink to 4PIN MOCO — 48V + CAN"></a></h3><p>Connects to the <code>PWR-CAN</code> port (<code>PWR/CAN</code> on a version 2 panel) and breaks out <strong>battery power and the CAN bus</strong> together. For actuators and devices driven over CAN.</p><a class="rbq-card-cta" href="/RBQ/manual/interface/external-port#pwr-can">Pin map →</a></div><div class="rbq-card"><h3 id="cable-2pin">2PIN MOCO — 48V<a class="header-anchor" href="#cable-2pin" aria-label="Permalink to 2PIN MOCO — 48V"></a></h3><p>Connects to the <code>POWER</code> port and carries <strong>battery power only</strong>. For loads that need no communication link.</p><a class="rbq-card-cta" href="/RBQ/manual/interface/external-port#power">Pin map →</a></div></div><div class="sb sb-caution"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">CAUTION</p><p>The two 48 V cables carry <strong>raw battery voltage</strong>, which moves between 42.0 V and 58.4 V with the state of charge. Add your own converter if the payload needs a regulated supply. Design within the per-port current limit — <code>POWER</code> 5 A, <code>PWR-CAN</code> 10 A, <code>12V/LAN</code> 2–3 A.</p></div></div><p>How to mate and release the connectors is covered in <a href="/RBQ/manual/maintenance/connector.html">Connector handling</a>; switching power on to a port is covered in <a href="/RBQ/manual/interface/port-power.html">Powering the external ports</a>.</p>',13)])])}const B=h(b,[["render",g]]);export{R as __pageData,B as default};
